{"implementation": "def solve(case):
    # Validate payload structure
    if not isinstance(case, dict) or 'payload' not in case:
        raise ValueError('Invalid case structure')
    payload = case['payload']
    if 'segments' not in payload or 'budget' not in payload:
        raise ValueError('Missing required fields')
    segments = payload['segments']
    budget = payload['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('budget must be a non-negative integer')

    # Validate each segment
    for seg in segments:
        if not isinstance(seg, dict):
            raise ValueError('Each segment must be a dict')
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in seg:
                raise ValueError(f'Missing key {key} in segment')
            if not isinstance(seg[key], int):
                raise ValueError(f'{key} must be integer')
        if seg['minimum'] < 0 or seg['capacity'] < 0:
            raise ValueError('minimum and capacity must be non-negative')
        if seg['minimum'] > seg['capacity']:
            raise ValueError('minimum exceeds capacity')

    # Check feasibility
    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget not between sum of minima and sum of capacities')

    # Initialize allocations at minima
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - total_min

    # Allocate remaining tokens greedily
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                next_pos = allocations[i] + 1
                score = seg['importance'] / next_pos
                if score > best_score:
                    best_score = score
                    best_idx = i
                elif score == best_score and best_idx != -1:
                    # Tie: keep earlier original order (lower index)
                    if i < best_idx:
                        best_idx = i
        if best_idx == -1:
            # Should not happen because remaining > 0 but no segment has capacity
            raise ValueError('Unexpected: no segment with available capacity')
        allocations[best_idx] += 1
        remaining -= 1

    # Build result
    result_allocations = []
    name_mapping = {}
    for i, seg in enumerate(segments):
        result_allocations.append({'name': seg['name'], 'allocated': allocations[i]})
        name_mapping[seg['name']] = allocations[i]
    conserved_total = sum(allocations)

    return {
        'allocations': result_allocations,
        'name_mapping': name_mapping,
        'conserved_total': conserved_total
    }"}
